ActiveTutorialLocalData.tab = {
[1] = {1, 1, "Event\u{0020}Tutorial", "This\u{0020}event\u{0020}is\u{0020}divided\u{0020}into\u{0020}exploration,\u{0020}challenge,\u{0020}and\u{0020}trial\u{0020}levels.\u{0020}Passing\u{0020}certain\u{0020}exploration\u{0020}levels\u{0020}unlocks\u{0020}the\u{0020}corresponding\u{0020}challenge\u{0020}levels.\u{0020}Items\u{0020}obtained\u{0020}by\u{0020}passing\u{0020}challenge\u{0020}levels\u{0020}are\u{0020}used\u{0020}to\u{0020}challenge\u{0020}trial\u{0020}levels.", "TutorialPic/Img_Yindao_xh_1", "0", "0", "0", "活動引導", "本次活動分為探索關卡，挑戰關卡，試煉關卡；通關指定探索關卡可解鎖對應的挑戰關卡，通過挑戰關卡獲取的試煉道具用於挑戰試煉關卡。"},
[2] = {2, 1, "Event\u{0020}Tutorial", "Once\u{0020}you've\u{0020}cleared\u{0020}all\u{0020}the\u{0020}exploration\u{0020}levels\u{0020}within\u{0020}a\u{0020}chapter,\u{0020}you\u{0020}unlock\u{0020}corresponding\u{0020}trial\u{0020}levels.\u{0020}Take\u{0020}on\u{0020}and\u{0020}complete\u{0020}these\u{0020}trials\u{0020}to\u{0020}obtain\u{0020}Tear\u{0020}of\u{0020}Ziz\u{0020}and\u{0020}Dragon\u{0020}Jade,\u{0020}which\u{0020}you\u{0020}can\u{0020}exchange\u{0020}for\u{0020}rewards\u{0020}at\u{0020}the\u{0020}Wish\u{0020}Exchange.", "TutorialPic/Img_Yindao_xh_2", "0", "0", "0", "活動引導", "通關章節內的所有探索關卡後可解鎖對應的試煉關卡，進行試煉可獲得席茲之淚，龍之玉隨後前往心願交換處換取獎勵吧。"},
[3] = {3, 1, "Event\u{0020}Tutorial", "Having\u{0020}begun\u{0020}the\u{0020}exploration,\u{0020}tap\u{0020}on\u{0020}a\u{0020}plot\u{0020}of\u{0020}land\u{0020}to\u{0020}move\u{0020}around.", "TutorialPic/Img_Yindao_xh_3", "0", "0", "0", "活動引導", "進入探索關卡後點擊地塊操作領航在地圖中移動。"},
[4] = {4, 1, "Event\u{0020}Tutorial", "Completing\u{0020}the\u{0020}level's\u{0020}objectives\u{0020}unlocks\u{0020}the\u{0020}subsequent\u{0020}level.\u{0020}You\u{0020}can\u{0020}choose\u{0020}to\u{0020}leave\u{0020}or\u{0020}continue\u{0020}to\u{0020}explore\u{0020}the\u{0020}current\u{0020}level.\u{0020}You\u{0020}can\u{0020}leave\u{0020}at\u{0020}any\u{0020}time\u{0020}while\u{0020}exploring.", "TutorialPic/Img_Yindao_xh_4", "0", "0", "0", "活動引導", "完成關卡目標後將解鎖後續關卡可以選擇離開或在當前關卡中繼續探索，探索過程中也可以隨時離開關卡。"},
[5] = {5, 1, "Event\u{0020}Tutorial", "You\u{0020}can\u{0020}fully\u{0020}explore\u{0020}normal\u{0020}exploration\u{0020}maps\u{0020}by\u{0020}continuing\u{0020}to\u{0020}explore.\u{0020}However,\u{0020}in\u{0020}special\u{0020}exploration\u{0020}levels\u{0020}you\u{0020}can\u{0020}only\u{0020}see\u{0020}grids\u{0020}around\u{0020}you.", "TutorialPic/Img_Yindao_xh_6", "0", "0", "0", "活動引導", "普通探索關卡中會隨著領航在地圖中前進可以發現全部的地圖，但在特殊探索關卡中領航只能查看自身周圍的格子。"},
[6] = {6, 1, "Event\u{0020}Tutorial", "You\u{0020}may\u{0020}encounter\u{0020}events\u{0020}while\u{0020}out\u{0020}exploring.\u{0020}Should\u{0020}you\u{0020}be\u{0020}defeated\u{0020}in\u{0020}combat,\u{0020}you\u{0020}won't\u{0020}lose\u{0020}any\u{0020}exploration\u{0020}progress\u{0020}and\u{0020}can\u{0020}simply\u{0020}restart\u{0020}the\u{0020}battle.", "TutorialPic/Img_Yindao_xh_7", "0", "0", "0", "活動引導", "在探索過程中會觸發各種事件，在戰鬥時若戰敗不會影響探索進度可以重新進行戰鬥。"},
[7] = {7, 1, "Event\u{0020}Tutorial", "Some\u{0020}levels\u{0020}include\u{0020}temporarily\u{0020}impassable\u{0020}roadblocks.\u{0020}Defeat\u{0020}the\u{0020}designated\u{0020}enemies\u{0020}or\u{0020}converse\u{0020}with\u{0020}the\u{0020}designated\u{0020}characters\u{0020}to\u{0020}remove\u{0020}them.", "TutorialPic/Img_Yindao_xh_8", "0", "0", "0", "活動引導", "在部分關卡中會存在暫時無法通行的路障，擊敗指定敵人或與指定角色對話將自動解除。"},
[8] = {8, 1, "Event\u{0020}Tutorial", "Special\u{0020}exploration\u{0020}levels\u{0020}may\u{0020}include\u{0020}trap\u{0020}grids,\u{0020}which\u{0020}look\u{0020}identical\u{0020}to\u{0020}ordinary\u{0020}grids.\u{0020}So\u{0020}be\u{0020}sure\u{0020}to\u{0020}proceed\u{0020}with\u{0020}caution.", "TutorialPic/Img_Yindao_xh_11", "0", "0", "0", "活動引導", "在特殊探索關卡中存在外觀與普通格相同的陷阱格，請小心的前進吧。"},
[9] = {9, 1, "Event\u{0020}Tutorial", "Special\u{0020}combat:\u{0020}Once\u{0020}the\u{0020}operation\u{0020}begins,\u{0020}two\u{0020}consecutive\u{0020}battles\u{0020}will\u{0020}be\u{0020}carried\u{0020}out\u{0020}with\u{0020}the\u{0020}current\u{0020}team.\u{0020}You\u{0020}can\u{0020}switch\u{0020}and\u{0020}view\u{0020}the\u{0020}enemy\u{0020}information\u{0020}through\u{0020}\"Enemy\u{0020}Formation\u{0020}Overview\"\u{0020}before\u{0020}the\u{0020}combat\u{0020}starts\u{0020}and\u{0020}adjust\u{0020}your\u{0020}team\u{0020}ahead\u{0020}of\u{0020}time.", "TutorialPic/Img_Yindao_xh_9", "0", "0", "0", "活動引導", "特殊戰鬥\u{0020}在作戰開始後會以當前隊伍連續進行兩場戰鬥，在作戰開始前可以通過'敵陣總覽'切換查看敵人資訊，合理的調整隊伍應對兩場戰鬥吧。"},
[10] = {10, 1, "Event\u{0020}Tutorial", "If\u{0020}you\u{0020}fail\u{0020}to\u{0020}defeat\u{0020}the\u{0020}trial\u{0020}target\u{0020}in\u{0020}a\u{0020}single\u{0020}trial,\u{0020}it\u{0020}will\u{0020}retain\u{0020}its\u{0020}remaining\u{0020}health.\u{0020}Achieve\u{0020}all\u{0020}victory\u{0020}conditions\u{0020}for\u{0020}the\u{0020}trial\u{0020}objective\u{0020}of\u{0020}a\u{0020}difficulty\u{0020}level\u{0020}to\u{0020}unlock\u{0020}the\u{0020}ability\u{0020}to\u{0020}Sweep\u{0020}that\u{0020}difficulty.", "TutorialPic/Img_Yindao_xh_10", "0", "0", "0", "活動引導", "單次試煉若未能擊敗試煉目標則會保留目標剩餘血量，每種難度的試煉目標需通關5次且達成所有勝利條件後可以解鎖對應難度的掃蕩功能。"},
[11] = {11, 2, "Event\u{0020}Tutorial", "The\u{0020}plot\u{0020}event\u{0020}is\u{0020}divided\u{0020}into\u{0020}plot\u{0020}levels,\u{0020}challenge\u{0020}levels,\u{0020}and\u{0020}trial\u{0020}levels.\nCompleting\u{0020}challenge\u{0020}levels\u{0020}grants\u{0020}the\u{0020}event\u{0020}item\u{0020}\"Radish\u{0020}Key\".", "TutorialPic/Img_Yindao_qrj_1", "0", "0", "0", "劇情活動引導", "劇情活動分為劇情關卡，挑戰關卡，試煉關卡；\n通關挑戰關卡可獲得活動道具「回憶的寶匣」。"},
[12] = {12, 2, "Event\u{0020}Tutorial", "The\u{0020}event\u{0020}item\u{0020}\"Radish\u{0020}Key\"\u{0020}can\u{0020}be\u{0020}exchanged\u{0020}for\u{0020}rewards\u{0020}with\u{0020}Karen\u{0020}at\u{0020}the\u{0020}event\u{0020}store.", "TutorialPic/Img_Yindao_qrj_2", "0", "0", "0", "劇情活動引導", "使用活動道具「回憶的寶匣」在活動商店中與妍妍蘿兌換獎勵吧。"},
[13] = {13, 3, "Moonlight\u{0020}Abysst\u{0020}Tutorial", "Moonlight\u{0020}Abyss\u{0020}is\u{0020}a\u{0020}limited-time\u{0020}event.\u{0020}Challenging\u{0020}abyss\u{0020}levels\u{0020}don't\u{0020}consume\u{0020}stamina.\u{0020}The\u{0020}friend\u{0020}assist\u{0020}function\u{0020}cannot\u{0020}be\u{0020}used\u{0020}during\u{0020}these\u{0020}levels.\u{0020}Complete\u{0020}a\u{0020}level\u{0020}on\u{0020}one\u{0020}tier\u{0020}unlocks\u{0020}the\u{0020}next\u{0020}tier's\u{0020}level.\u{0020}You\u{0020}cannot\u{0020}challenge\u{0020}levels\u{0020}you've\u{0020}already\u{0020}completed.\u{0020}\"Haze\"\u{0020}affects\u{0020}the\u{0020}Moonlight\u{0020}Abyss,\u{0020}which\u{0020}means\u{0020}that\u{0020}special\u{0020}effects\u{0020}will\u{0020}be\u{0020}generated\u{0020}for\u{0020}both\u{0020}the\u{0020}enemy\u{0020}and\u{0020}our\u{0020}side\u{0020}during\u{0020}battles.", "TutorialPic/Img_Yindao_yssy_1", "0", "0", "0", "月色深淵引導", "月色深淵為限時活動，挑戰深淵關卡不需要消耗體力，關卡中無法使用好友助戰功能，完成一層的關卡後就會解鎖下一層的關卡，已通過的關卡無法重複挑戰，在月色深淵中由於『蒼霧特性』的影響，在戰鬥中會對敵我雙方產生特殊效果。"},
[14] = {14, 3, "Moonlight\u{0020}Abysst\u{0020}Tutorial", "Your\u{0020}drivers\u{0020}retain\u{0020}their\u{0020}remaining\u{0020}health\u{0020}(percentage)\u{0020}after\u{0020}each\u{0020}battle\u{0020}in\u{0020}the\u{0020}Moonlight\u{0020}Abyss.\u{0020}Similarly,\u{0020}if\u{0020}you\u{0020}are\u{0020}defeated,\u{0020}the\u{0020}enemy\u{0020}units\u{0020}also\u{0020}retain\u{0020}their\u{0020}health\u{0020}(percentage).", "TutorialPic/Img_Yindao_yssy_2", "0", "0", "0", "月色深淵引導", "在月色深淵中每場戰鬥結束後，我方駕駛員的剩餘生命值（百分比）將會被全數繼承，若我方戰敗時則敵方單位的生命值（百分比）也會全數繼承。"},
[15] = {15, 3, "Moonlight\u{0020}Abysst\u{0020}Tutorial", "You\u{0020}can\u{0020}reset\u{0020}your\u{0020}drivers'\u{0020}status\u{0020}before\u{0020}a\u{0020}battle.\u{0020}Doing\u{0020}so\u{0020}fully\u{0020}heals\u{0020}your\u{0020}drivers.\u{0020}You\u{0020}can\u{0020}do\u{0020}this\u{0020}three\u{0020}times\u{0020}per\u{0020}day.\u{0020}The\u{0020}first\u{0020}every\u{0020}day\u{0020}is\u{0020}free\u{0020}of\u{0020}charge,\u{0020}while\u{0020}subsequent\u{0020}resets\u{0020}require\u{0020}a\u{0020}small\u{0020}amount\u{0020}of\u{0020}Energy\u{0020}Cubes.\u{0020}(In\u{0020}the\u{0020}hard\u{0020}mode,\u{0020}resetting\u{0020}your\u{0020}drivers'\u{0020}status\u{0020}does\u{0020}not\u{0020}use\u{0020}Energy\u{0020}Cubes)", "TutorialPic/Img_Yindao_yssy_3", "0", "0", "0", "月色深淵引導", "在戰鬥前可以選擇重置駕駛員狀態，重置後所有駕駛員恢復為滿血狀態，每日可以進行3次重置操作，每日首次重置駕駛員狀態時免費，後續每次重置將需消耗少量能源晶體。（困難模式時，重置駕駛員狀態不消耗能源晶體）"},
[16] = {16, 3, "Moonlight\u{0020}Abysst\u{0020}Tutorial", "There\u{0020}are\u{0020}two\u{0020}modes\u{0020}in\u{0020}the\u{0020}Moonlight\u{0020}Abyss:\u{0020}normal\u{0020}and\u{0020}hard.\u{0020}After\u{0020}clearing\u{0020}all\u{0020}the\u{0020}levels\u{0020}on\u{0020}normal\u{0020}difficulty,\u{0020}you\u{0020}unlock\u{0020}hard\u{0020}mode.", "TutorialPic/Img_Yindao_yssy_4", "0", "0", "0", "月色深淵引導", "月色深淵中分為普通與困難兩種模式，通關所有普通難度的關卡後將解鎖困難模式。"},
[17] = {17, 3, "Moonlight\u{0020}Abysst\u{0020}Tutorial", "Before\u{0020}starting\u{0020}hard\u{0020}mode,\u{0020}you\u{0020}need\u{0020}to\u{0020}set\u{0020}the\u{0020}corresponding\u{0020}\"Haze\".\u{0020}You\u{0020}can\u{0020}reset\u{0020}the\u{0020}progress\u{0020}of\u{0020}hard\u{0020}levels\u{0020}at\u{0020}any\u{0020}time\u{0020}and\u{0020}re-select\u{0020}the\u{0020}\"Haze\".", "TutorialPic/Img_Yindao_yssy_5", "0", "0", "0", "月色深淵引導", "開始困難模式前需要設置對應的『蒼霧特性』，玩家可以隨時重置困難關卡的進度，重新選擇『蒼霧特性』進行挑戰。"},
[18] = {18, 3, "Moonlight\u{0020}Abysst\u{0020}Tutorial", "Clearing\u{0020}hard\u{0020}mode\u{0020}gives\u{0020}you\u{0020}a\u{0020}spot\u{0020}in\u{0020}the\u{0020}rankings.\u{0020}The\u{0020}ranking\u{0020}you\u{0020}receive\u{0020}is\u{0020}based\u{0020}on\u{0020}the\u{0020}\"Haze\"\u{0020}level\u{0020}and\u{0020}how\u{0020}long\u{0020}it\u{0020}took\u{0020}for\u{0020}you\u{0020}to\u{0020}clear\u{0020}it.", "TutorialPic/Img_Yindao_yssy_6", "0", "0", "0", "月色深淵引導", "完全通關困難模式後計入排名，將根據玩家通關時的『蒼霧特性』等級，通關時間先後進行排名。"},
[19] = {19, 4, "Event\u{0020}Tutorial", "The\u{0020}side\u{0020}story\u{0020}event\u{0020}is\u{0020}divided\u{0020}into\u{0020}area\u{0020}exploration\u{0020}and\u{0020}trial\u{0020}stages.\u{0020}Area\u{0020}exploration\u{0020}includes\u{0020}story\u{0020}and\u{0020}battle\u{0020}stages,\u{0020}while\u{0020}trial\u{0020}stages\u{0020}require\u{0020}the\u{0020}event\u{0020}item\u{0020}\"One-Day\u{0020}Manager\u{0020}Pass.\"", "TutorialPic/Img_Yindao_xxyj_1", "0", "0", "0", "外傳活動引導", "外傳活動分為區域探索與試煉關卡，在區域探索中設有劇情與戰鬥關卡；\n參與試煉關卡需要消耗活動道具「星之遺物」。"},
[20] = {20, 4, "Event\u{0020}Tutorial", "All\u{0020}stages\u{0020}in\u{0020}the\u{0020}side\u{0020}story\u{0020}event\u{0020}have\u{0020}energy\u{0020}reserve\u{0020}requirements.\u{0020}If\u{0020}your\u{0020}team's\u{0020}energy\u{0020}reserve\u{0020}meets\u{0020}the\u{0020}requirements,\u{0020}you'll\u{0020}receive\u{0020}stat\u{0020}boosts\u{0020}during\u{0020}battles;\u{0020}if\u{0020}it\u{0020}doesn't,\u{0020}your\u{0020}stats\u{0020}will\u{0020}be\u{0020}reduced.\u{0020}You\u{0020}can\u{0020}check\u{0020}the\u{0020}reserve\u{0020}details\u{0020}for\u{0020}specific\u{0020}effects.", "TutorialPic/Img_Yindao_xxyj_2", "0", "0", "0", "外傳活動引導", "外傳活動中所有關卡都設有能源儲備需求，若隊伍能源儲備值滿足關卡所需時在戰鬥中可獲得屬性提升效果，反之若不滿足則在戰鬥中將會降低屬性，具體效果可通過儲備詳情處查看；"},
[21] = {21, 4, "Event\u{0020}Tutorial", "In\u{0020}area\u{0020}exploration,\u{0020}you\u{0020}can\u{0020}obtain\u{0020}the\u{0020}event\u{0020}item\u{0020}\"Nimbus\u{0020}Core\u{0020}Fragments.\"\u{0020}Collecting\u{0020}these\u{0020}fragments\u{0020}allows\u{0020}you\u{0020}to\u{0020}upgrade\u{0020}StarChange\u{0020}expansion\u{0020}parts,\u{0020}increasing\u{0020}your\u{0020}team's\u{0020}energy\u{0020}reserve.", "TutorialPic/Img_Yindao_xxyj_3", "0", "0", "0", "外傳活動引導", "在區域探索中可獲取活動道具「絕望要素」，收集「絕望要素」可用於提升星變拓展件等級，增加隊伍能源儲備值"},
[22] = {22, 4, "Event\u{0020}Tutorial", "Participating\u{0020}in\u{0020}the\u{0020}side\u{0020}story\u{0020}event\u{0020}also\u{0020}grants\u{0020}you\u{0020}the\u{0020}event\u{0020}item\u{0020}\"Lucky\u{0020}Gacha\u{0020}Coin.\"\u{0020}Use\u{0020}the\u{0020}Lucky\u{0020}Gacha\u{0020}Coin\u{0020}to\u{0020}play\u{0020}the\u{0020}gashapon\u{0020}and\u{0020}earn\u{0020}rewards.", "TutorialPic/Img_Yindao_xxyj_4", "0", "0", "0", "外傳活動引導", "參與外傳活動可獲取活動道具「宅急送優惠券」，使用「宅急送優惠券」可在飛速食品宅急送進行訂單派送並獲得獎勵。"},
[23] = {23, 4, "Event\u{0020}Tutorial", "This\u{0020}event\u{0020}features\u{0020}7\u{0020}regular\u{0020}gashapon\u{0020}machines\u{0020}and\u{0020}1\u{0020}unlimited\u{0020}gashapon\u{0020}machine.\u{0020}Each\u{0020}regular\u{0020}gashapon\u{0020}machine\u{0020}contains\u{0020}one\u{0020}of\u{0020}Chiaki's\u{0020}favorite\u{0020}collectibles.\u{0020}When\u{0020}you\u{0020}obtain\u{0020}a\u{0020}collectible\u{0020}from\u{0020}the\u{0020}current\u{0020}machine,\u{0020}you\u{0020}can\u{0020}choose\u{0020}to\u{0020}switch\u{0020}to\u{0020}the\u{0020}next\u{0020}one.\u{0020}Note:\u{0020}Once\u{0020}you\u{0020}switch,\u{0020}you\u{0020}cannot\u{0020}return\u{0020}to\u{0020}the\u{0020}previous\u{0020}machine.\u{0020}The\u{0020}unlimited\u{0020}gashapon\u{0020}machine\u{0020}does\u{0020}not\u{0020}contain\u{0020}collectibles;\u{0020}it\u{0020}resets\u{0020}after\u{0020}you've\u{0020}drawn\u{0020}all\u{0020}items.", "TutorialPic/Img_Yindao_xxyj_5", "0", "0", "0", "外傳活動引導", "本次活動設有7個普通宅急送訂單機與1個無限宅急送訂單，當獲取當前宅急送訂單中所有特殊殘響道具時可選擇切換至下一個宅急送訂單，注：切換後將無法返回上一個宅急送訂單；無限宅急送訂單中不包含特殊殘響道具，需要派送全部訂單物品後可重置無限宅急送訂單；"},
[24] = {24, 4, "Event\u{0020}Tutorial", "During\u{0020}the\u{0020}event,\u{0020}collect\u{0020}Chiaki's\u{0020}favorite\u{0020}collectibles\u{0020}to\u{0020}earn\u{0020}rewards!", "TutorialPic/Img_Yindao_xxyj_6", "0", "0", "0", "外傳活動引導", "本次活動設有7個普通宅急送訂單機與1個無限宅急送訂單，當獲取當前宅急送訂單中所有特殊殘響道具時可選擇切換至下一個宅急送訂單，注：切換後將無法返回上一個宅急送訂單；無限宅急送訂單中不包含特殊殘響道具，需要派送全部訂單物品後可重置無限宅急送訂單；"},
[25] = {25, 4001, "Event\u{0020}Tutorial", "Side\u{0020}story\u{0020}events\u{0020}are\u{0020}divided\u{0020}into\u{0020}area\u{0020}exploration\u{0020}and\u{0020}trial\u{0020}levels.\u{0020}Area\u{0020}exploration\u{0020}includes\u{0020}story\u{0020}and\u{0020}battle\u{0020}levels.\nParticipating\u{0020}in\u{0020}trial\u{0020}levels\u{0020}requires\u{0020}the\u{0020}event\u{0020}item\u{0020}\"Star\u{0020}Relics\".", "TutorialPic/Img_Yindao_wzhd_1", "0", "0", "0", "外傳活動引導", "外傳活動分為區域探索與試煉關卡，在區域探索中設有劇情與戰鬥關卡；\n參與試煉關卡需要消耗活動道具「星之遺物」。"},
[26] = {26, 4001, "Event\u{0020}Tutorial", "All\u{0020}side\u{0020}story\u{0020}event\u{0020}levels\u{0020}have\u{0020}energy\u{0020}reserve\u{0020}requirements.\u{0020}If\u{0020}your\u{0020}team's\u{0020}energy\u{0020}reserve\u{0020}value\u{0020}meets\u{0020}the\u{0020}requirements\u{0020}of\u{0020}the\u{0020}level,\u{0020}you\u{0020}will\u{0020}gain\u{0020}stat\u{0020}enhancement\u{0020}during\u{0020}the\u{0020}battle.\u{0020}Conversely,\u{0020}if\u{0020}your\u{0020}energy\u{0020}reserve\u{0020}doesn't\u{0020}meet\u{0020}the\u{0020}requirements,\u{0020}your\u{0020}stats\u{0020}will\u{0020}be\u{0020}reduced\u{0020}during\u{0020}the\u{0020}battle.\u{0020}You\u{0020}can\u{0020}view\u{0020}the\u{0020}specific\u{0020}effects\u{0020}via\u{0020}reserve\u{0020}details.", "TutorialPic/Img_Yindao_wzhd_2", "0", "0", "0", "外傳活動引導", "外傳活動中所有關卡都設有能源儲備需求，若隊伍能源儲備值滿足關卡所需時在戰鬥中可獲得屬性提升效果，反之若不滿足則在戰鬥中將會降低屬性，具體效果可通過儲備詳情處查看；"},
[27] = {27, 4001, "Event\u{0020}Tutorial", "You\u{0020}can\u{0020}obtain\u{0020}the\u{0020}event\u{0020}item\u{0020}\"Elements\u{0020}of\u{0020}Despair\"\u{0020}in\u{0020}area\u{0020}exploration.\u{0020}\"Elements\u{0020}of\u{0020}Despair\"\u{0020}can\u{0020}be\u{0020}used\u{0020}to\u{0020}upgrade\u{0020}the\u{0020}level\u{0020}of\u{0020}star\u{0020}transformation\u{0020}expansion\u{0020}parts\u{0020}and\u{0020}increase\u{0020}your\u{0020}team's\u{0020}energy\u{0020}reserve\u{0020}value.", "TutorialPic/Img_Yindao_wzhd_3", "0", "0", "0", "外傳活動引導", "在區域探索中可獲取活動道具「絕望要素」，收集「絕望要素」可用於提升星變拓展件等級，增加隊伍能源儲備值"},
[28] = {28, 4001, "Event\u{0020}Tutorial", "You\u{0020}can\u{0020}get\u{0020}the\u{0020}event\u{0020}item\u{0020}\"Home\u{0020}Delivery\u{0020}Express\u{0020}Coupon\"\u{0020}by\u{0020}participating\u{0020}in\u{0020}the\u{0020}side\u{0020}story\u{0020}event.\u{0020}Use\u{0020}the\u{0020}\"Home\u{0020}Delivery\u{0020}Express\u{0020}Coupon\"\u{0020}to\u{0020}place\u{0020}an\u{0020}order\u{0020}for\u{0020}delivery\u{0020}at\u{0020}Speedy\u{0020}Food\u{0020}Home\u{0020}Delivery\u{0020}and\u{0020}obtain\u{0020}rewards.", "TutorialPic/Img_Yindao_wzhd_4", "0", "0", "0", "外傳活動引導", "參與外傳活動可獲取活動道具「宅急送優惠券」，使用「宅急送優惠券」可在飛速食品宅急送進行訂單派送並獲得獎勵。"},
[29] = {29, 4001, "Event\u{0020}Tutorial", "This\u{0020}event\u{0020}has\u{0020}7\u{0020}regular\u{0020}Home\u{0020}Delivery\u{0020}Express\u{0020}orders\u{0020}and\u{0020}1\u{0020}unlimited\u{0020}order.\u{0020}Once\u{0020}you've\u{0020}obtained\u{0020}all\u{0020}the\u{0020}special\u{0020}reverb\u{0020}items\u{0020}in\u{0020}the\u{0020}current\u{0020}Home\u{0020}Delivery\u{0020}Express\u{0020}order,\u{0020}you\u{0020}can\u{0020}choose\u{0020}to\u{0020}switch\u{0020}to\u{0020}the\u{0020}next\u{0020}order.\nNote:\u{0020}After\u{0020}switching,\u{0020}you\u{0020}cannot\u{0020}return\u{0020}to\u{0020}the\u{0020}previous\u{0020}Home\u{0020}Delivery\u{0020}Express\u{0020}order\u{0020}again.\u{0020}The\u{0020}unlimited\u{0020}Home\u{0020}Delivery\u{0020}Express\u{0020}order\u{0020}does\u{0020}not\u{0020}contain\u{0020}special\u{0020}reverb\u{0020}items.\u{0020}Instead,\u{0020}delivering\u{0020}all\u{0020}the\u{0020}items\u{0020}will\u{0020}simply\u{0020}reset\u{0020}the\u{0020}unlimited\u{0020}Home\u{0020}Delivery\u{0020}Express.", "TutorialPic/Img_Yindao_wzhd_5", "0", "0", "0", "外傳活動引導", "本次活動設有7個普通宅急送訂單機與1個無限宅急送訂單，當獲取當前宅急送訂單中所有特殊殘響道具時可選擇切換至下一個宅急送訂單，注：切換後將無法返回上一個宅急送訂單；無限宅急送訂單中不包含特殊殘響道具，需要派送全部訂單物品後可重置無限宅急送訂單；"},
[30] = {30, 5, "Event\u{0020}Tutorial", "This\u{0020}event\u{0020}is\u{0020}divided\u{0020}into\u{0020}story\u{0020}and\u{0020}trial\u{0020}chapters.\u{0020}Story\u{0020}chapters\u{0020}are\u{0020}then\u{0020}further\u{0020}divided\u{0020}into\u{0020}story\u{0020}levels\u{0020}and\u{0020}exploration\u{0020}levels.", "TutorialPic/Img_Yindao_xh_12", "0", "0", "0", "半周年活動引導", "本次活動分為故事章節與試煉章節，在故事章節中分為劇情關卡與探索關卡；"},
[31] = {31, 5, "Event\u{0020}Tutorial", "Clearing\u{0020}trial\u{0020}levels\u{0020}grants\u{0020}the\u{0020}event\u{0020}item\u{0020}\"Proof\u{0020}of\u{0020}Changing\u{0020}the\u{0020}Future\".\u{0020}You\u{0020}can\u{0020}exchange\u{0020}\"Proof\u{0020}of\u{0020}Changing\u{0020}the\u{0020}Future\"\u{0020}for\u{0020}rewards\u{0020}with\u{0020}Tsukumo\u{0020}Tamaki\u{0020}at\u{0020}the\u{0020}event\u{0020}store.", "TutorialPic/Img_Yindao_xh_13", "0", "0", "0", "半周年活動引導", "通關試煉關卡可獲得活動道具「改變未來的證明」，使用道具「改變未來的證明」在活動商店中與九十九環兌換獎勵吧。"},
[32] = {32, 5, "Event\u{0020}Tutorial", "You\u{0020}can\u{0020}obtain\u{0020}the\u{0020}event\u{0020}item\u{0020}\"One-Day\u{0020}Pass\"\u{0020}via\u{0020}the\u{0020}event\u{0020}store.\u{0020}Use\u{0020}\"One-Day\u{0020}Pass\"\u{0020}to\u{0020}help\u{0020}Dolores\u{0020}complete\u{0020}simulation\u{0020}training\u{0020}and\u{0020}obtain\u{0020}rewards.\u{0020}Complete\u{0020}the\u{0020}simulation\u{0020}to\u{0020}unlock\u{0020}the\u{0020}memory.", "TutorialPic/Img_Yindao_xh_14", "0", "0", "0", "半周年活動引導", "通過活動商店獲得活動道具「一日通行证證」，使用道具「一日通行证」幫助多洛莉絲完成模擬訓練來獲得獎勵，完成模擬來解鎖回憶劇情吧。"},
[33] = {33, 5, "Event\u{0020}Tutorial", "Having\u{0020}begun\u{0020}the\u{0020}exploration\u{0020}level,\u{0020}tap\u{0020}on\u{0020}a\u{0020}plot\u{0020}of\u{0020}land\u{0020}to\u{0020}move\u{0020}around.\u{0020}Press\u{0020}the\u{0020}View\u{0020}button\u{0020}to\u{0020}switch\u{0020}to\u{0020}the\u{0020}map\u{0020}viewing\u{0020}mode.", "TutorialPic/Img_Yindao_xh_3", "0", "0", "0", "半周年活動引導", "進入探索關卡後點擊地塊操作領航在地圖中移，通過查看按鈕可以切換為查看地圖模式；"},
[34] = {34, 5, "Event\u{0020}Tutorial", "Completing\u{0020}the\u{0020}exploration\u{0020}level's\u{0020}objectives\u{0020}unlocks\u{0020}the\u{0020}subsequent\u{0020}level.\u{0020}You\u{0020}can\u{0020}choose\u{0020}to\u{0020}leave\u{0020}or\u{0020}continue\u{0020}to\u{0020}explore\u{0020}the\u{0020}current\u{0020}level.\u{0020}You\u{0020}can\u{0020}leave\u{0020}at\u{0020}any\u{0020}time\u{0020}while\u{0020}exploring.", "TutorialPic/Img_Yindao_xh_4", "0", "0", "0", "半周年活動引導", "在探索關卡中完成關卡目標後將解鎖後續關卡可以選擇離開或在當前關卡中繼續探索，探索過程中也可以隨時離開關卡。"},
[35] = {35, 5, "Event\u{0020}Tutorial", "You\u{0020}may\u{0020}encounter\u{0020}events\u{0020}while\u{0020}out\u{0020}exploring.\u{0020}Should\u{0020}you\u{0020}be\u{0020}defeated\u{0020}in\u{0020}combat,\u{0020}you\u{0020}won't\u{0020}lose\u{0020}any\u{0020}exploration\u{0020}progress\u{0020}and\u{0020}can\u{0020}simply\u{0020}restart\u{0020}the\u{0020}battle.", "TutorialPic/Img_Yindao_xh_7", "0", "0", "0", "半周年活動引導", "在探索過程中會觸發各種事件，在戰鬥時若戰敗不會影響探索進度可以重新進行戰鬥。"},
[36] = {36, 5, "Event\u{0020}Tutorial", "Some\u{0020}levels\u{0020}include\u{0020}temporarily\u{0020}impassable\u{0020}roadblocks.\u{0020}Defeat\u{0020}the\u{0020}designated\u{0020}enemies\u{0020}or\u{0020}converse\u{0020}with\u{0020}the\u{0020}designated\u{0020}characters\u{0020}to\u{0020}remove\u{0020}them.", "TutorialPic/Img_Yindao_xh_8", "0", "0", "0", "半周年活動引導", "在部分關卡中會存在暫時無法通行的路障，擊敗指定敵人或與指定角色對話將自動解除。"},
[37] = {37, 5, "Event\u{0020}Tutorial", "Some\u{0020}levels\u{0020}contain\u{0020}teleportation\u{0020}vortices.\u{0020}Entering\u{0020}a\u{0020}vortex\u{0020}will\u{0020}immediately\u{0020}teleport\u{0020}you\u{0020}to\u{0020}the\u{0020}corresponding\u{0020}teleportation\u{0020}vortex.", "TutorialPic/Img_Yindao_xh_15", "0", "0", "0", "半周年活動引導", "在部分關卡中會存在傳送旋渦，進入旋渦將會立刻被傳送至對應的另一個傳送旋渦處。"},
[38] = {38, 5, "Event\u{0020}Tutorial", "Special\u{0020}combat:\u{0020}Once\u{0020}the\u{0020}operation\u{0020}begins,\u{0020}two\u{0020}consecutive\u{0020}battles\u{0020}will\u{0020}be\u{0020}carried\u{0020}out\u{0020}with\u{0020}the\u{0020}current\u{0020}team.\u{0020}You\u{0020}can\u{0020}switch\u{0020}and\u{0020}view\u{0020}the\u{0020}enemy\u{0020}information\u{0020}through\u{0020}\"Enemy\u{0020}Formation\u{0020}Overview\"\u{0020}before\u{0020}the\u{0020}combat\u{0020}starts\u{0020}and\u{0020}adjust\u{0020}your\u{0020}team\u{0020}ahead\u{0020}of\u{0020}time.", "TutorialPic/Img_Yindao_xh_9", "0", "0", "0", "半周年活動引導", "特殊戰鬥\u{0020}在作戰開始後會以當前隊伍連續進行兩場戰鬥，在作戰開始前可以通過'敵陣總覽'切換查看敵人資訊，合理的調整隊伍應對兩場戰鬥吧。"},
[39] = {39, 5, "Event\u{0020}Tutorial", "If\u{0020}you\u{0020}fail\u{0020}to\u{0020}defeat\u{0020}the\u{0020}trial\u{0020}target\u{0020}in\u{0020}a\u{0020}single\u{0020}trial,\u{0020}it\u{0020}will\u{0020}retain\u{0020}its\u{0020}remaining\u{0020}health.\u{0020}Achieve\u{0020}all\u{0020}victory\u{0020}conditions\u{0020}for\u{0020}the\u{0020}trial\u{0020}objective\u{0020}of\u{0020}a\u{0020}difficulty\u{0020}level\u{0020}to\u{0020}unlock\u{0020}the\u{0020}ability\u{0020}to\u{0020}Sweep\u{0020}that\u{0020}difficulty.", "TutorialPic/Img_Yindao_xh_16", "0", "0", "0", "半周年活動引導", "單次試煉若未能擊敗試煉目標則會保留目標剩餘血量，每種難度的試煉目標達成所有勝利條件後可以解鎖對應難度的掃蕩功能。"},
[40] = {40, 6, "Event\u{0020}Tutorial", "Clearing\u{0020}trial\u{0020}levels\u{0020}grants\u{0020}the\u{0020}event\u{0020}item\u{0020}\"Holy\u{0020}Water\u{0020}Drop\".\u{0020}You\u{0020}can\u{0020}exchange\u{0020}\"Holy\u{0020}Water\u{0020}Drop\"\u{0020}for\u{0020}rewards\u{0020}with\u{0020}Meria\u{0020}at\u{0020}the\u{0020}event\u{0020}store.", "TutorialPic/Img_Yindao_yzn_1", "0", "0", "0", "1周年活動引導", "通關試煉關卡可獲得活動道具「聖水滴」，使用道具「聖水滴」在活動商店中與梅莉雅兌換獎勵吧。"},
[41] = {41, 6, "Event\u{0020}Tutorial", "You\u{0020}can\u{0020}obtain\u{0020}the\u{0020}event\u{0020}item\u{0020}\"One-day\u{0020}Training\u{0020}Coupon\"\u{0020}via\u{0020}the\u{0020}event\u{0020}store.\u{0020}Use\u{0020}\"One-day\u{0020}Training\u{0020}Coupon\"\u{0020}to\u{0020}help\u{0020}Kosgaard\u{0020}complete\u{0020}simulation\u{0020}training\u{0020}and\u{0020}earn\u{0020}rewards.", "TutorialPic/Img_Yindao_yzn_2", "0", "0", "0", "1周年活動引導", "通過活動商店獲得活動道具「一日特訓券」，使用道具「一日特訓券」幫助珂斯嘉德完成模擬訓練來獲得獎勵。"},
[42] = {42, 996, "Cosmic\u{0020}Showdown\u{0020}Tutorial", "Ranking\u{0020}Rules:\u{0020}Players\u{0020}are\u{0020}ranked\u{0020}based\u{0020}on\u{0020}their\u{0020}Max\u{0020}Winning\u{0020}Streak.", "TutorialPic/Img_Yindao_wudaohui_1", "0", "0", "0", "0", "0"},
[43] = {43, 996, "Cosmic\u{0020}Showdown\u{0020}Tutorial", "The\u{0020}same\u{0020}character\u{0020}cannot\u{0020}be\u{0020}deployed\u{0020}in\u{0020}both\u{0020}the\u{0020}Offensive\u{0020}Lineup\u{0020}and\u{0020}the\u{0020}Defensive\u{0020}Lineup.", "TutorialPic/Img_Yindao_wudaohui_2", "0", "0", "0", "0", "0"},
[44] = {44, 996, "Cosmic\u{0020}Showdown\u{0020}Tutorial", "Battle\u{0020}Sequence:\u{0020}In\u{0020}Round\u{0020}1,\u{0020}your\u{0020}team's\u{0020}Offensive\u{0020}Lineup\u{0020}faces\u{0020}the\u{0020}opponent's\u{0020}Defensive\u{0020}Lineup.\u{0020}In\u{0020}Round\u{0020}2,\u{0020}the\u{0020}opponent's\u{0020}Offensive\u{0020}Lineup\u{0020}faces\u{0020}your\u{0020}team's\u{0020}Defensive\u{0020}Lineup.", "TutorialPic/Img_Yindao_wudaohui_3", "0", "0", "0", "0", "0"},
[45] = {45, 997, "Tutorial", "Follow\u{0020}the\u{0020}designated\u{0020}route\u{0020}and\u{0020}apply\u{0020}soap!", "TutorialPic/Img_CuozaoBangzhu1", "0", "0", "0", "肥皂泡泡", "沿著規定好的路線，為駕駛員打上肥皂吧！"},
[46] = {46, 997, "Tutorial", "The\u{0020}correct\u{0020}route\u{0020}will\u{0020}allow\u{0020}for\u{0020}the\u{0020}most\u{0020}efficient\u{0020}use\u{0020}of\u{0020}soap.\u{0020}The\u{0020}shorter\u{0020}the\u{0020}completion\u{0020}time,\u{0020}the\u{0020}higher\u{0020}the\u{0020}score.", "TutorialPic/Img_CuozaoBangzhu2", "0", "0", "0", "肥皂泡泡", "正確的路線，能最大效率的利用肥皂~完成時間越短，評分越高"},
[47] = {47, 998, "Tutorial", "As\u{0020}this\u{0020}operation\u{0020}takes\u{0020}place\u{0020}underwater,\u{0020}creatures\u{0020}that\u{0020}inhabit\u{0020}these\u{0020}waters\u{0020}may\u{0020}occasionally\u{0020}cling\u{0020}to\u{0020}the\u{0020}driver.", "TutorialPic/Img_CuozaoBangzhu3", "0", "0", "0", "捕捉水生動物", "因在海洋作戰，偶爾會有棲息於此的生物掛在駕駛員身上"},
[48] = {48, 998, "Tutorial", "Timing\u{0020}is\u{0020}key—tap\u{0020}the\u{0020}button\u{0020}at\u{0020}the\u{0020}right\u{0020}moment\u{0020}to\u{0020}help\u{0020}the\u{0020}driver\u{0020}get\u{0020}rid\u{0020}of\u{0020}the\u{0020}creatures\u{0020}clinging\u{0020}to\u{0020}her!", "TutorialPic/Img_CuozaoBangzhu4", "0", "0", "0", "捕捉水生動物", "看準時機點擊螢幕按鈕，幫助駕駛員趕走身上的動物吧！"},
[49] = {49, 999, "Tutorial", "Select\u{0020}the\u{0020}most\u{0020}suitable\u{0020}skincare\u{0020}products\u{0020}for\u{0020}your\u{0020}driver.\u{0020}FYI,\u{0020}the\u{0020}appropriate\u{0020}products\u{0020}may\u{0020}vary\u{0020}depending\u{0020}on\u{0020}the\u{0020}region.\nDon't\u{0020}choose\u{0020}the\u{0020}wrong\u{0020}skincare\u{0020}product,\u{0020}as\u{0020}different\u{0020}products\u{0020}have\u{0020}different\u{0020}effects.", "TutorialPic/Img_CuozaoBangzhu5", "0", "0", "0", "抉擇！護膚品之謎", "為駕駛員挑選最合適的護膚品吧，不同地區的駕駛員適用的護膚品也不同\n可不要選錯護膚品哦，不同的護膚品，保養功效也不同~"},
[50] = {50, 999, "Tutorial", "Carefully\u{0020}read\u{0020}each\u{0020}question\u{0020}and\u{0020}choose\u{0020}the\u{0020}most\u{0020}suitable\u{0020}option.\u{0020}The\u{0020}more\u{0020}questions\u{0020}you\u{0020}answer\u{0020}correctly,\u{0020}the\u{0020}more\u{0020}appropriate\u{0020}the\u{0020}selected\u{0020}skincare\u{0020}products\u{0020}will\u{0020}be.", "TutorialPic/Img_CuozaoBangzhu6", "0", "0", "0", "抉擇！護膚品之謎", "仔細看好每個問題，才能選出最適合駕駛員的那一款~答對的題目越多，選擇的護膚品就越合適"},
[51] = {51, 1000, "Tutorial", "Seize\u{0020}the\u{0020}moment\u{0020}and\u{0020}tap\u{0020}the\u{0020}avatar\u{0020}of\u{0020}the\u{0020}appearing\u{0020}lead\u{0020}navigator's\u{0020}avatar!", "TutorialPic/Img_Yindao_BathGame1", "0", "0", "0", "按摩點擊", "把握時機，點擊出現的領航頭像吧！"},
[52] = {52, 1000, "Tutorial", "The\u{0020}more\u{0020}successful\u{0020}taps\u{0020}you\u{0020}make,\u{0020}the\u{0020}more\u{0020}you\u{0020}help\u{0020}the\u{0020}driver\u{0020}relax,\u{0020}thus\u{0020}earning\u{0020}yourself\u{0020}a\u{0020}higher\u{0020}score.", "TutorialPic/Img_Yindao_BathGame1", "0", "0", "0", "按摩點擊", "點擊成功的次數越多，越能幫助駕駛員放松身心，獲得的評分也會越高。"},
[53] = {53, 1001, "Tutorial", "Carefully\u{0020}observe\u{0020}the\u{0020}marks\u{0020}on\u{0020}the\u{0020}driver's\u{0020}body\u{0020}and\u{0020}select\u{0020}the\u{0020}correct\u{0020}tool\u{0020}to\u{0020}help\u{0020}clean\u{0020}them.\nDrag\u{0020}the\u{0020}tool\u{0020}and\u{0020}swipe\u{0020}across\u{0020}the\u{0020}marks\u{0020}to\u{0020}clean\u{0020}her\u{0020}up.", "TutorialPic/Img_Yindao_BathGame3", "0", "0", "0", "清潔身體", "仔細觀察駕駛員身上的痕跡，並選擇正確的道具，為駕駛員清潔身體。\n拖動道具，滑動經過身上的痕跡，即可完成清潔。"},
[54] = {54, 1001, "Tutorial", "Finally,\u{0020}apply\u{0020}lipstick\u{0020}to\u{0020}the\u{0020}driver\u{0020}to\u{0020}complete\u{0020}the\u{0020}synesthesia\u{0020}maintenance.\nSwipe\u{0020}the\u{0020}screen\u{0020}to\u{0020}drag\u{0020}and\u{0020}apply\u{0020}the\u{0020}lipstick\u{0020}to\u{0020}the\u{0020}driver's\u{0020}lips\u{0020}and\u{0020}complete\u{0020}the\u{0020}synesthesia\u{0020}maintenance.", "TutorialPic/Img_Yindao_BathGame3", "0", "0", "0", "清潔身體", "最後，為駕駛員抹上口紅，完成通感維護。\n拖動口紅，滑動經過駕駛員的嘴唇，即可完成通感維護。"},
[55] = {55, 1002, "Tutorial", "Follow\u{0020}the\u{0020}rhythm\u{0020}of\u{0020}the\u{0020}palm\u{0020}to\u{0020}massage\u{0020}the\u{0020}driver.\nTap\u{0020}at\u{0020}the\u{0020}correct\u{0020}finger\u{0020}positions\u{0020}at\u{0020}the\u{0020}right\u{0020}moment\u{0020}to\u{0020}give\u{0020}the\u{0020}driver\u{0020}a\u{0020}relaxing\u{0020}massage.", "TutorialPic/Img_Yindao_BathGame2", "0", "0", "0", "節奏按摩", "跟隨手掌與捶打的節奏，為駕駛員按摩。\n在正確的時機點擊手指的位置，即可為駕駛員進行節奏按摩。"},
[56] = {56, 1002, "Tutorial", "Achieve\u{0020}more\u{0020}successful\u{0020}massages\u{0020}to\u{0020}earn\u{0020}a\u{0020}higher\u{0020}score.", "TutorialPic/Img_Yindao_BathGame2", "0", "0", "0", "節奏按摩", "連續成功的按摩次數越多，分數越高。"},
[57] = {57, 1003, "Tutorial", "Synesthesia\u{0020}Maintenance\u{0020}is\u{0020}where\u{0020}you\u{0020}can\u{0020}have\u{0020}more\u{0020}in-depth\u{0020}communication\u{0020}with\u{0020}your\u{0020}drivers.", "TutorialPic/Img_Yindao_cz_1", "0", "0", "0", "通感維護", "「通感維護」是與駕駛員進行更深入交流的地方。"},
[58] = {58, 1003, "Tutorial", "Meet\u{0020}a\u{0020}driver's\u{0020}affinity\u{0020}level\u{0020}requirements\u{0020}and\u{0020}use\u{0020}the\u{0020}specified\u{0020}consumable\u{0020}item\u{0020}to\u{0020}engage\u{0020}in\u{0020}'Synesthesia\u{0020}Maintenance'\u{0020}with\u{0020}them.", "TutorialPic/Img_Yindao_cz_2", "0", "0", "0", "通感維護", "滿足駕駛員的好感條件，並使用指定的消耗道具後，即可與駕駛員進行「通感維護」。"},
[59] = {59, 7, "Tutorial", "The\u{0020}event\u{0020}is\u{0020}divided\u{0020}into\u{0020}Story\u{0020}Chapters\u{0020}and\u{0020}Trial\u{0020}Chapters.\u{0020}In\u{0020}the\u{0020}Story\u{0020}Chapters,\u{0020}there\u{0020}are\u{0020}Story\u{0020}Stages\u{0020}and\u{0020}Exploration\u{0020}Stages.", "TutorialPic/Img_Yindao_xh_1", "0", "0", "0", "0", "0"},
[60] = {60, 7, "Tutorial", "Completing\u{0020}Trial\u{0020}Stages\u{0020}rewards\u{0020}event\u{0020}item,\u{0020}New\u{0020}Cheston\u{0020}Token\u{0020}which\u{0020}can\u{0020}be\u{0020}exchanged\u{0020}for\u{0020}items\u{0020}in\u{0020}the\u{0020}Event\u{0020}Shop.", "TutorialPic/Img_Yindao_xh_2", "0", "0", "0", "0", "0"},
[61] = {61, 7, "Tutorial", "Obtain\u{0020}the\u{0020}event\u{0020}item\u{0020}Kitty\u{0020}Request\u{0020}Form\u{0020}from\u{0020}the\u{0020}Event\u{0020}Shop\u{0020}to\u{0020}unlock\u{0020}rewards\u{0020}and\u{0020}special\u{0020}memory\u{0020}stories.", "TutorialPic/Img_Yindao_xh_3", "0", "0", "0", "0", "0"},
[62] = {62, 7, "Tutorial", "If\u{0020}the\u{0020}trial\u{0020}target\u{0020}is\u{0020}not\u{0020}defeated\u{0020}in\u{0020}a\u{0020}single\u{0020}challenge,\u{0020}the\u{0020}remaining\u{0020}HP\u{0020}will\u{0020}carry\u{0020}over\u{0020}to\u{0020}the\u{0020}next\u{0020}attempt.\u{0020}Once\u{0020}all\u{0020}victory\u{0020}conditions\u{0020}are\u{0020}met\u{0020}for\u{0020}a\u{0020}difficulty\u{0020}level,\u{0020}the\u{0020}Sweep\u{0020}Function\u{0020}for\u{0020}that\u{0020}level\u{0020}will\u{0020}be\u{0020}unlocked.", "TutorialPic/Img_Yindao_xh_4", "0", "0", "0", "0", "0"},
[63] = {63, 8, "Personal\u{0020}Story\u{0020}Event\u{0020}Guide", "During\u{0020}the\u{0020}event,\u{0020}unlock\u{0020}and\u{0020}clear\u{0020}Act\u{0020}4\u{0020}of\u{0020}the\u{0020}event\u{0020}story\u{0020}to\u{0020}obtain\u{0020}the\u{0020}character\u{0020}outfit.", "TutorialPic/Img_Yindao_grjq_1", "0", "0", "0", "0", "0"},
[64] = {64, 8, "Personal\u{0020}Story\u{0020}Event\u{0020}Guide", "Participate\u{0020}in\u{0020}the\u{0020}event\u{0020}to\u{0020}obtain\u{0020}the\u{0020}event\u{0020}item\u{0020}\"Echo\u{0020}Token.\"\u{0020}Use\u{0020}\"Echo\u{0020}Token\"\u{0020}to\u{0020}draw\u{0020}in\u{0020}\"Echoes\u{0020}of\u{0020}Ripples\"\u{0020}and\u{0020}receive\u{0020}rewards.", "TutorialPic/Img_Yindao_grjq_2", "0", "0", "0", "0", "0"},
[65] = {65, 8, "Personal\u{0020}Story\u{0020}Event\u{0020}Guide", "This\u{0020}event\u{0020}features\u{0020}8\u{0020}limited\u{0020}gacha\u{0020}machines\u{0020}and\u{0020}1\u{0020}unlimited\u{0020}gacha\u{0020}machine.\u{0020}Once\u{0020}you\u{0020}have\u{0020}obtained\u{0020}all\u{0020}items\u{0020}from\u{0020}the\u{0020}current\u{0020}gacha\u{0020}machine,\u{0020}you\u{0020}may\u{0020}choose\u{0020}to\u{0020}switch\u{0020}to\u{0020}the\u{0020}next\u{0020}one.\nNote:\u{0020}After\u{0020}switching,\u{0020}you\u{0020}will\u{0020}not\u{0020}be\u{0020}able\u{0020}to\u{0020}return\u{0020}to\u{0020}the\u{0020}previous\u{0020}gacha\u{0020}machine.", "TutorialPic/Img_Yindao_grjq_3", "0", "0", "0", "0", "0"},
